add_action( 'woocommerce_after_add_to_cart_form', 'perfectpixel_product_page_shipping_rates' );

function perfectpixel_product_page_shipping_rates() {
	global $product;
	if ( ! $product || ! $product->needs_shipping() || ! class_exists( 'WC_Shipping_Zones' ) ) {
		return;
	}
	$zones   = WC_Shipping_Zones::get_zones();
	$zones[] = array( 'zone_id' => 0 ); // "Rest of the world".
	$rows    = array();

	foreach ( $zones as $data ) {
		$zone    = new WC_Shipping_Zone( $data['zone_id'] );
		$methods = array();
		foreach ( $zone->get_shipping_methods( true ) as $method ) {
			$label = $method->get_title();
			if ( isset( $method->cost ) && is_numeric( $method->cost ) && (float) $method->cost > 0 ) {
				$label .= ' ' . wc_price( $method->cost );
			} elseif ( 'free_shipping' === $method->id && ! empty( $method->min_amount ) ) {
				$label .= ' ' . esc_html( '{{product_shipping_free_from}}' ) . ' ' . wc_price( $method->min_amount );
			}
			$methods[] = $label;
		}
		if ( $methods ) {
			$name   = $data['zone_id'] ? $zone->get_zone_name() : __( 'Locations not covered by your other zones', 'woocommerce' );
			$rows[] = '<li><strong>' . esc_html( $name ) . ':</strong> ' . wp_kses_post( implode( ' &middot; ', $methods ) ) . '</li>';
		}
	}
	if ( $rows ) {
		echo '<div class="perfectpixel-product-shipping"><h4>' . esc_html( '{{product_shipping_heading}}' ) . '</h4><ul>' . implode( '', $rows ) . '</ul></div>';
	}
}
